 A partially ordered set or poset  is a set $P$ equipped with a binary relation $\leq$ such that for all $x, y, $ and $z \in P$,
\begin{enumerate}
\item $x \leq x$,
\item $x \leq y$ and $y \leq x$ imply $x = y$,
\item $x \leq y$ and $y \leq z$ imply $x \leq z$. 
\end{enumerate}

 \label{cones} Let $V$ be a Euclidean space with positive definite inner product $<- , ->$. A subset $C \subseteq V$ is called a {\bf cone} if $C$ satisfies  conditions (1) and (2) below:
\begin{enumerate}
\item $0 \in C$,
\item If $v \in C$, then $\Bbb{R}_{\geq 0}v \subseteq  C$.

\noindent
\leftline{C is called a {\bf convex cone} if it also satisfies the property:}

\item If $u, v \in C$, then $u + v \in C$.

\noindent 
A convex cone $C$  is a  {\bf pointed convex cone}
 if it is a convex cone and satisfies the property:
\item  $C \cap (-C) = \{0\}$.
\end{enumerate}

 \label{hatcone} Let $X$ and $Y$ be subsets of $S^n$.
\begin{enumerate}
\item $X = \widehat{X} \cap S^n$ and   if 
$C$ is any cone  in $\Bbb{R}^{n + 1}$ with $X = C\cap S^n$, then $\widehat{X} = C$,
\item  $X\cap Y = \emptyset$, if and only if  $\widehat{X} \cap \widehat{Y} = \{0\}$.
\end{enumerate}

 \label{halfspaceintersect}
Let $V$ be a Euclidean space with positive definite inner product \\$<- , ->$ and let $u, v \in V$. Then 
$H_u^{int} \cap H_v^{int}$ is non-empty if $ u \not= -cv, \ c > 0$.

 \label{projection}
Let $X$ be an element of $\mathcal{L}_n$, then $X \cap \Bbb{R}^{n }$ is an 
element of $\mathcal{L}_{n - 1}$, where $\Bbb{R}^n $ is imbedded  in   $\Bbb{R}^{n + 1} $ as in Section \ref{intro}.
